167	// Special handler for Result-returning endpoints
168	const handleApiResponseAsResult = async <T, E>(
169	  response: Response
170	): Promise<Result<T, E>> => {
171	  if (!response.ok) {
172	    // HTTP error - no structured error data
173	    let errorMessage = `Request failed with status ${response.status}`;
174	
175	    try {
176	      const errorData = await response.json();
177	      if (errorData.message) {
178	        errorMessage = errorData.message;
179	      }
180	    } catch {
181	      errorMessage = response.statusText || errorMessage;
182	    }
183	
184	    return {
185	      success: false,
186	      error: undefined,
187	      message: errorMessage,
188	    };
189	  }
190	
191	  const result: ApiResponse<T, E> = await response.json();
192	
193	  if (!result.success) {
194	    return {
195	      success: false,
196	      error: result.error_data || undefined,
197	      message: result.message || undefined,
198	    };
199	  }
200	
201	  return { success: true, data: result.data as T };
202	};
203	
204	export const handleApiResponse = async <T, E = T>(
205	  response: Response
206	): Promise<T> => {
207	  if (!response.ok) {
208	    let errorMessage = `Request failed with status ${response.status}`;
209	
210	    try {
211	      const errorData = await response.json();
212	      if (errorData.message) {
213	        errorMessage = errorData.message;
214	      }
215	    } catch {
216	      // Fallback to status text if JSON parsing fails
217	      errorMessage = response.statusText || errorMessage;
218	    }
219	
220	    console.error('[API Error]', {
221	      message: errorMessage,
222	      status: response.status,
223	      response,
224	      endpoint: response.url,
225	      timestamp: new Date().toISOString(),
226	    });
227	    throw new ApiError<E>(errorMessage, response.status, response);
228	  }
229	
230	  if (response.status === 204) {
231	    return undefined as T;
232	  }
233	
234	  const result: ApiResponse<T, E> = await response.json();
235	
236	  if (!result.success) {
237	    // Check for error_data first (structured errors), then fall back to message
238	    if (result.error_data) {
239	      console.error('[API Error with data]', {
240	        error_data: result.error_data,
241	        message: result.message,
242	        status: response.status,
243	        response,
244	        endpoint: response.url,
245	        timestamp: new Date().toISOString(),
246	      });
247	      // Throw a properly typed error with the error data
248	      throw new ApiError<E>(
249	        result.message || 'API request failed',
250	        response.status,
251	        response,
252	        result.error_data
253	      );
254	    }
255	
256	    console.error('[API Error]', {
257	      message: result.message || 'API request failed',
258	      status: response.status,
259	      response,
260	      endpoint: response.url,
261	      timestamp: new Date().toISOString(),
262	    });
263	    throw new ApiError<E>(
264	      result.message || 'API request failed',
265	      response.status,
266	      response
267	    );
268	  }
269	
270	  return result.data as T;
271	};
