31	const ATTACHMENT_MARKDOWN_PATTERN = /(!?)\[([^\]]*)\]\(([^)]+)\)/g;
32	
33	interface AttachmentMarkdownMatch {
34	  prefix: string;
35	  label: string;
36	  src: string;
37	  start: number;
38	  end: number;
39	}
40	
41	function findAttachmentMarkdownMatches(
42	  content: string
43	): AttachmentMarkdownMatch[] {
44	  const matches: AttachmentMarkdownMatch[] = [];
45	
46	  for (const match of content.matchAll(ATTACHMENT_MARKDOWN_PATTERN)) {
47	    const fullMatch = match[0];
48	    const start = match.index;
49	    if (start == null) {
50	      continue;
51	    }
52	
53	    matches.push({
54	      prefix: match[1] ?? '',
55	      label: match[2] ?? '',
56	      src: match[3] ?? '',
57	      start,
58	      end: start + fullMatch.length,
59	    });
60	  }
61	
62	  return matches;
63	}
64	
65	function normalizeAttachmentWhitespace(content: string): string {
66	  return content
67	    .replace(/[ \t]+\n/g, '\n')
68	    .replace(/\n[ \t]+/g, '\n')
69	    .replace(/\n{3,}/g, '\n\n');
70	}
71	
72	function removeAttachmentSlice(
73	  content: string,
74	  start: number,
75	  end: number
76	): string {
77	  let before = content.slice(0, start);
78	  let after = content.slice(end);
79	
80	  if (before.length === 0 && after.startsWith('\n')) {
81	    after = after.slice(1);
82	  } else if (after.length === 0 && before.endsWith('\n')) {
83	    before = before.slice(0, -1);
84	  } else if (before.endsWith('\n') && after.startsWith('\n')) {
85	    after = after.slice(1);
86	  } else if (before.endsWith(' ') && after.startsWith(' ')) {
87	    after = after.slice(1);
88	  }
89	
90	  return normalizeAttachmentWhitespace(before + after);
91	}
