10	function toAbsoluteWsUrl(pathOrUrl: string): string {
11	  if (/^wss?:\/\//i.test(pathOrUrl)) {
12	    return pathOrUrl;
13	  }
14	
15	  if (/^https?:\/\//i.test(pathOrUrl)) {
