3	// Constants for height calculation
4	const HEADER_HEIGHT = 48; // px - collapsed state
5	const LINE_HEIGHT = 20; // px - approximate line height in diff view
6	const PADDING = 16; // px - top/bottom padding
7	const SPACING = 8; // px - space between items (pb-base = 0.5rem)
8	
9	/**
10	 * Estimate the height of a diff item based on its content.
11	 * Used by virtuoso for better scroll position estimation.
12	 */
13	export function estimateDiffHeight(diff: Diff, isExpanded: boolean): number {
14	  if (!isExpanded) {
15	    return HEADER_HEIGHT + SPACING;
16	  }
17	
18	  // For expanded diffs, estimate based on line count
19	  const lineCount = (diff.additions ?? 0) + (diff.deletions ?? 0);
20	  // Add some buffer for hunk headers, context lines, etc.
21	  const estimatedLines = Math.max(lineCount * 1.2, 10);
22	
23	  return HEADER_HEIGHT + estimatedLines * LINE_HEIGHT + PADDING + SPACING;
24	}
25	
26	/**
27	 * Calculate a reasonable default height for the virtuoso list.
28	 * Uses median of estimated heights for better accuracy.
29	 */
30	export function calculateDefaultHeight(diffs: Diff[]): number {
31	  if (diffs.length === 0) return 200;
32	
33	  // Assume most diffs start expanded for modified files
34	  const heights = diffs.map((diff) => estimateDiffHeight(diff, true));
35	  heights.sort((a, b) => a - b);
36	
37	  // Return median
38	  const mid = Math.floor(heights.length / 2);
39	  return heights.length % 2 === 0
40	    ? (heights[mid - 1] + heights[mid]) / 2
41	    : heights[mid];
42	}
