112	   */
113	  stop(): void {
114	    if (this.messageListener) {
115	      window.removeEventListener('message', this.messageListener);
116	      this.messageListener = null;
117	    }
118	  }
119	
120	  /**
121	   * Update event handlers
122	   */
123	  setHandlers(handlers: EventHandlers): void {
124	    this.handlers = { ...this.handlers, ...handlers };
125	  }
126	
127	  /**
128	   * Send a message to the iframe (if needed)
129	   */
130	  sendToIframe(iframe: HTMLIFrameElement, message: unknown): void {
131	    if (iframe.contentWindow) {
132	      iframe.contentWindow.postMessage(message, '*');
133	    }
134	  }
135	}
