137	// Convenience function for quick setup
138	export function listenToClickToComponent(
139	  handlers: EventHandlers
140	): ClickToComponentListener {
141	  const listener = new ClickToComponentListener(handlers);
142	  listener.start();
143	  return listener;
144	}
